Here's a Python program that meets your requirements. This program uses a dictionary to store the contacts and follows the specified input/output format.

```python
# Initialize an empty phonebook dictionary
phonebook = {}

def add_contact():
    """Add a contact to the phonebook."""
    name = input("Enter the name: ")
    phone_number = input("Enter the phone number: ")
    phonebook[name] = phone_number
    print(f"Contact added: {name} {phone_number}")

def remove_contact():
    """Remove a contact from the phonebook."""
    name = input("Enter the name of the contact to remove: ")
    if name in phonebook:
        del phonebook[name]
        print(f"Contact removed: {name}")
    else:
        print(f"Contact {name} not found.")

def search_contact():
    """Search for a contact in the phonebook."""
    name = input("Enter the name to search: ")
    if name in phonebook:
        print(f"{name}: {phonebook[name]}")
    else:
        print(f"Contact {name} not found.")

# Main menu
while True:
    print("\nPhonebook Menu")
    print("1. Add Contact")
    print("2. Remove Contact")
    print("3. Search Contact")
    print("4. Exit")

    choice = input("Enter your choice: ")

    if choice == "1":
        add_contact()
    elif choice == "2":
        remove_contact()
    elif choice == "3":
        search_contact()
    elif choice == "4":
        print("Exiting Phonebook...")
        break
    else:
        print("Invalid choice. Please try again.")
```

This program will allow you to add, remove, and search for contacts in a phonebook using a dictionary.
